def write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content.rstrip() + "\n", encoding="utf-8")
    print("Wrote:", path.relative_to(ROOT))


def patch_main() -> None:
    text = MAIN.read_text(encoding="utf-8")
    import_line = "from app.routes.extra import router as extra_router"
    if import_line not in text:
        anchor = "from app.routes.matches import router as matches_router"
        if anchor in text:
            text = text.replace(anchor, anchor + "\n" + import_line, 1)
        else:
            text = import_line + "\n" + text
    if "app.include_router(extra_router)" not in text:
        marker = "\n@app."
        pos = text.find(marker)
        if pos != -1:
            text = text[:pos] + "\napp.include_router(extra_router)\n" + text[pos:]
        else:
            text += "\napp.include_router(extra_router)\n"
    MAIN.write_text(text, encoding="utf-8")
    print("Patched: backend/app/main.py")


def main() -> None:
    if not BACKEND.exists() or not FRONTEND.exists():
        raise SystemExit("Run this script from the CRICMASTER project root.")
    write(EXTRA, EXTRA_PY)
    for rel, body in PAGES.items():
        write((FRONTEND / "pages" / rel) if rel.endswith(".html") else (FRONTEND / "js" / rel), body)
    patch_main()
    print()
    print("===============================================")
    print("CRICMASTER REMAINING FEATURES BATCH INSTALLED")
    print("===============================================")
    print("Stats / Search / Standings / Series")
    print("News adapter / Profile / Settings / Admin")
    print("Refreshed Home dashboard")
    print()
    print("No database data was deleted or re-imported.")


if __name__ == "__main__":
    main()
